def longest_k_distinct(text, limit):
    if limit < 0:
        return None
    counts = {}
    distinct = 0
    left = 0
    best = [0, 0]
    for right in range(len(text)):
        char = text[right]
        if char not in counts:
            counts[char] = 0
        if counts[char] == 0:
            distinct = distinct + 1
        counts[char] = counts[char] + 1
        while distinct > limit:
            old = text[left]
            counts[old] = counts[old] - 1
            if counts[old] == 0:
                distinct = distinct - 1
            left = left + 1
        if right + 1 - left > best[1] - best[0]:
            best = [left, right + 1]
    return best

