def subarray_sum_count(values, target):
    frequencies = {0: 1}
    prefix = 0
    result = 0
    for value in values:
        prefix = prefix + value
        wanted = prefix - target
        if wanted in frequencies:
            result = result + frequencies[wanted]
        if prefix not in frequencies:
            frequencies[prefix] = 0
        frequencies[prefix] = frequencies[prefix] + 1
    return result

