def sorted_pair(values, target):
    for i in range(1, len(values)):
        if values[i] < values[i - 1]:
            return None
    left = 0
    right = len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return [left, right]
        if total < target:
            left = left + 1
        else:
            right = right - 1
    return []

