def shortest_window(values, target):
    if target <= 0:
        return None
    for value in values:
        if value < 0:
            return None
    best = []
    left = 0
    total = 0
    for right in range(len(values)):
        total = total + values[right]
        while left <= right and total >= target:
            if len(best) == 0 or right + 1 - left < best[1] - best[0]:
                best = [left, right + 1]
            total = total - values[left]
            left = left + 1
    return best

