def longest_unique_window(text):
    last = {}
    left = 0
    best = [0, 0]
    for right in range(len(text)):
        char = text[right]
        if char in last and last[char] >= left:
            left = last[char] + 1
        last[char] = right
        if right + 1 - left > best[1] - best[0]:
            best = [left, right + 1]
    return best

